body.script:
//
{
  "@context":"https://schema.org",
  "@type":"LocalBusiness",
  "name":"SM Traders",
  "description":"Electrical services, rooftop solar installation, installation and maintenance.",
  "url":"YOUR_WEBSITE_URL",
  "telephone":"YOUR_PHONE",
  "address":{"@type":"PostalAddress","streetAddress":"YOUR_ADDRESS","addressCountry":"IN"},
  "founder":[{"@type":"Person","name":"Mangesh Yendhe"},{"@type":"Person","name":"Omkar Yendhe"}],
  "areaServed":"India"
}
//

//
(function () {
  "use strict";

  /* =========================================================
     CONFIGURATION — EDIT THIS BLOCK ONLY
     ========================================================= */
  var SM_WHATSAPP = "YOUR_WHATSAPP_NUMBER";

  var SM_CONFIG = {
    businessName: "SM Traders",
    owners: {
      mangesh: {
        name: "Mangesh Yendhe",
        role: "OWNER",
        image: "MANGESH_PROFILE_IMAGE_URL",
        initials: "MY",
        focus: "Electrical & Solar Solutions",
        tags: ["Electrical", "Solar", "Installation"],
        bio: "Hands-on electrical professional leading installation and solar projects for residential and commercial spaces. Focused on reliable, neat, safe and long-lasting work."
      },
      omkar: {
        name: "Omkar Yendhe",
        role: "CO-FOUNDER",
        image: "OMKAR_PROFILE_IMAGE_URL",
        initials: "OY",
        focus: "Electrical & Solar Solutions",
        tags: ["Electrical", "Solar", "Service"],
        bio: "Handles service execution, site coordination and maintenance support — ensuring every job is completed properly and supported continuously afterwards."
      }
    },
    phone: "YOUR_PHONE",
    whatsapp: SM_WHATSAPP,
    email: "YOUR_EMAIL",
    address: "YOUR_ADDRESS",
    heroImage: "HERO_IMAGE_URL",
    solarImage: "SOLAR_IMAGE_URL",
    beforeImage: "BEFORE_IMAGE_URL",
    afterImage: "AFTER_IMAGE_URL",
    projects: [
      { title: "Rooftop Solar — Residence", cat: "solar residential", desc: "Panel mounting, inverter setup and electrical integration.", image: "PROJECT_1_IMAGE_URL" },
      { title: "Commercial Distribution Board", cat: "electrical commercial", desc: "New board with MCB/RCCB protection and circuit labelling.", image: "PROJECT_2_IMAGE_URL" },
      { title: "Complete House Wiring", cat: "electrical residential", desc: "Full concealed wiring with proper earthing and load testing.", image: "PROJECT_3_IMAGE_URL" },
      { title: "Shop Lighting Setup", cat: "electrical commercial", desc: "LED layout, high-efficiency fixtures and power points.", image: "PROJECT_4_IMAGE_URL" },
      { title: "Solar Inverter Room", cat: "solar commercial", desc: "Inverter, protection devices and neat cable management.", image: "PROJECT_5_IMAGE_URL" },
      { title: "Inverter & Battery Backup", cat: "electrical residential", desc: "Backup system installation, safety wiring and setup.", image: "PROJECT_6_IMAGE_URL" }
    ],
    products: [
      { t: "Wires & Cables", d: "House wiring cables, multi-core industrial cables and flexible copper wires." },
      { t: "Switches & Sockets", d: "Modular switches, sockets, cover plates and surface boxes." },
      { t: "MCB / RCCB", d: "Circuit breakers, isolators, RCCB protection and distribution boards." },
      { t: "LED Lighting", d: "Indoor panels, outdoor floodlights, commercial LED fixtures and tubelights." },
      { t: "Inverter & Batteries", d: "Home backup power systems, tubular batteries and heavy-duty battery racks." },
      { t: "Solar Components", d: "Solar panels, structure mounting hardware, DC cables and AC/DC protection boxes." }
    ],
    faq: [
      ["What electrical services does SM Traders provide?", "House wiring, electrical repairs, distribution board upgrades, MCB/RCCB installation, lighting solutions, inverter and battery backup setup, and scheduled maintenance for homes and commercial shops."],
      ["Do you install rooftop solar systems?", "Yes. We handle rooftop solar end-to-end — site inspection, mounting structure, panels, inverter, cabling, safety protection and final commissioning."],
      ["Do you handle residential work?", "Yes. New house wiring, rewiring, fault repairs, lighting setups and backup power installations."],
      ["Do you handle commercial work?", "Yes. Shops, offices, showrooms and commercial premises for complete electrical and solar installations."],
      ["How can I request a quotation?", "Fill out our enquiry form or contact us on WhatsApp with your location and requirements. Scope and pricing are confirmed after an on-site assessment."],
      ["Do you provide post-installation support?", "Yes. We stand behind our work and provide maintenance and technical support after installation."]
    ]
  };
  /* ===================== END CONFIGURATION ===================== */

  var $ = function (s, c) { return (c || document).querySelector(s); };
  var $$ = function (s, c) { return Array.prototype.slice.call((c || document).querySelectorAll(s)); };
  var isPlaceholder = function (v) { return !v || /_URL$|^YOUR_/.test(v); };
  var esc = function (s) { return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;"); };

  function waLink(msg) {
    var num = String(SM_CONFIG.whatsapp || "").replace(/[^0-9]/g, "");
    var text = encodeURIComponent(msg || "Hello SM Traders, I would like to enquire about your electrical/solar services.");
    if (!num) { return "#contact"; }
    return "https://wa.me/" + num + "?text=" + text;
  }

  /* ---------- Image Loader Helpers ---------- */
  function fillImage(hostId, url, alt, lazy) {
    var host = document.getElementById(hostId);
    if (!host || isPlaceholder(url)) { return; }
    var img = new Image();
    img.alt = alt || "";
    if (lazy) { img.loading = "lazy"; }
    img.decoding = "async";
    img.onload = function () { host.innerHTML = ""; host.appendChild(img); };
    img.onerror = function () { /* Keep default designed placeholder */ };
    img.src = url;
  }

  /* ---------- Config Injection into DOM ---------- */
  function applyConfig() {
    var y = $("#smYear"); if (y) { y.textContent = String(new Date().getFullYear()); }
    var map = { smInfoPhone: "phone", smInfoWa: "whatsapp", smInfoMail: "email", smInfoAddr: "address",
                smFootPhone: "phone", smFootMail: "email", smFootAddr: "address" };
    Object.keys(map).forEach(function (id) {
      var el = document.getElementById(id);
      if (el) { el.textContent = SM_CONFIG[map[id]] || ""; }
    });

    var tel = String(SM_CONFIG.phone || "").replace(/[^0-9+]/g, "");
    $$("#smCall, #smBarCall").forEach(function (a) { a.href = tel ? "tel:" + tel : "#contact"; });
    $$("#smWa, #smBarWa").forEach(function (a) { a.href = waLink(); });

    fillImage("smHeroShot", SM_CONFIG.heroImage, "Electrical and solar work by SM Traders", false);
    fillImage("smSolarShot", SM_CONFIG.solarImage, "Rooftop solar installation by SM Traders", true);
    fillImage("smBefore", SM_CONFIG.beforeImage, "Electrical installation before work", true);
    fillImage("smAfter", SM_CONFIG.afterImage, "Electrical installation after work", true);
  }

  /* ---------- Owner Profiles Rendering ---------- */
  function renderOwners() {
    var wrap = $("#smOwners");
    if (!wrap) { return; }
    var keys = ["mangesh", "omkar"];
    wrap.innerHTML = keys.map(function (k, i) {
      var o = SM_CONFIG.owners[k];
      var portrait = isPlaceholder(o.image)
        ? '<div class="sm-initials">' + esc(o.initials) + "</div>"
        : '<img loading="lazy" alt="' + esc(o.name) + '" src="' + esc(o.image) + '"/>';
      var tags = o.tags.map(function (t) { return "<span>" + esc(t) + "</span>"; }).join("");
      var firstName = o.name.split(" ")[0];
      return '<article class="sm-owner reveal">' +
        '<div class="sm-portrait">' + portrait + "</div>" +
        '<div class="sm-owner-body">' +
          '<span class="sm-badge' + (i === 1 ? " sm-badge-co" : "") + '"><i></i>' + esc(o.role) + '</span>' +
          '<h3>' + esc(o.name) + '</h3>' +
          '<span class="sm-owner-org">SM TRADERS</span>' +
          '<div class="sm-owner-focus">' + esc(o.focus) + '</div>' +
          '<p>' + esc(o.bio) + '</p>' +
          '<div class="sm-tags">' + tags + '</div>' +
          '<a class="sm-arrow sm-btn sm-btn-ghost" href="#contact" style="align-self:flex-start">Talk to ' + esc(firstName) + ' <span class="ar">&#8594;</span></a>' +
        '</div>' +
      '</article>';
    }).join("");

    $$(".sm-portrait img", wrap).forEach(function (img) {
      img.onerror = function () {
        var k = img.alt.indexOf("Omkar") > -1 ? "omkar" : "mangesh";
        img.parentNode.innerHTML = '<div class="sm-initials">' + SM_CONFIG.owners[k].initials + "</div>";
      };
    });
  }

  /* ---------- Products Rendering ---------- */
  function renderProducts() {
    var wrap = $("#smProducts");
    if (!wrap) { return; }
    wrap.innerHTML = SM_CONFIG.products.map(function (p) {
      return '<article class="reveal"><h3>' + esc(p.t) + "</h3><p>" + esc(p.d) + "</p>" +
        '<a href="' + waLink("Hello SM Traders, I would like to enquire about availability of: " + p.t) + '" target="_blank" rel="noopener">Enquire About Availability <span class="ar">&#8594;</span></a></article>';
    }).join("");
  }

  /* ---------- Projects & Portfolio Filtering & Lightbox ---------- */
  var gallery = [];
  function renderProjects() {
    var wrap = $("#smProjects");
    if (!wrap) { return; }
    gallery = SM_CONFIG.projects.slice();
    wrap.innerHTML = gallery.map(function (p, i) {
      var media = isPlaceholder(p.image)
        ? '<div class="sm-ph"><b>SM TRADERS</b><small>PROJECT IMAGE</small></div>'
        : '<img loading="lazy" alt="' + esc(p.title) + '" src="' + esc(p.image) + '"/>';
      return '<button class="sm-proj-card" type="button" data-i="' + i + '" data-cat="' + esc(p.cat) + '" aria-label="Open ' + esc(p.title) + '">' +
        '<span class="sm-proj-media">' + media + "</span>" +
        '<span class="sm-proj-body" style="display:block">' +
          "<b>" + esc(p.cat.split(" ")[0].toUpperCase()) + "</b>" +
          "<h3>" + esc(p.title) + "</h3><p>" + esc(p.desc) + "</p>" +
          '<span class="sm-arrow">View Project <span class="ar">&#8594;</span></span>' +
        "</span></button>";
    }).join("");
  }

  function initFilters() {
    var bar = $("#smFilters");
    var wrap = $("#smProjects");
    if (!bar || !wrap) { return; }
    bar.addEventListener("click", function (e) {
      var btn = e.target.closest("button[data-f]");
      if (!btn) { return; }
      $$("button", bar).forEach(function (b) { b.classList.remove("on"); });
      btn.classList.add("on");
      var f = btn.getAttribute("data-f");
      $$(".sm-proj-card", wrap).forEach(function (card) {
        var ok = f === "all" || (card.getAttribute("data-cat") || "").indexOf(f) > -1;
        card.classList.toggle("is-hidden", !ok);
      });
    });
  }

  var lb = { i: 0, open: false };
  function lbShow(i) {
    var box = $("#smLb");
    if (!box || !gallery.length) { return; }
    lb.i = (i + gallery.length) % gallery.length;
    var p = gallery[lb.i];
    var img = $("#smLbImg");
    var t = $("#smLbTitle");
    if (t) { t.textContent = p.title; }
    if (img) {
      img.alt = p.title;
      img.src = isPlaceholder(p.image)
        ? "data:image/svg+xml;charset=UTF-8," + encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="800"><rect width="1200" height="800" fill="#1A1D20"/><text x="600" y="400" fill="#F5B800" font-family="Inter,sans-serif" font-size="34" text-anchor="middle">SM TRADERS — PROJECT IMAGE</text></svg>')
        : p.image;
    }
    box.classList.add("open");
    document.body.classList.add("sm-lock");
    lb.open = true;
    var c = $("#smLbClose"); if (c) { c.focus(); }
  }
  function lbClose() {
    var box = $("#smLb");
    if (!box) { return; }
    box.classList.remove("open");
    document.body.classList.remove("sm-lock");
    lb.open = false;
  }
  function initLightbox() {
    var wrap = $("#smProjects");
    if (wrap) {
      wrap.addEventListener("click", function (e) {
        var card = e.target.closest(".sm-proj-card");
        if (card) { lbShow(parseInt(card.getAttribute("data-i"), 10) || 0); }
      });
    }
    var c = $("#smLbClose"), pv = $("#smLbPrev"), nx = $("#smLbNext"), box = $("#smLb");
    if (c) { c.addEventListener("click", lbClose); }
    if (pv) { pv.addEventListener("click", function () { lbShow(lb.i - 1); }); }
    if (nx) { nx.addEventListener("click", function () { lbShow(lb.i + 1); }); }
    if (box) {
      box.addEventListener("click", function (e) { if (e.target === box) { lbClose(); } });
      var sx = 0;
      box.addEventListener("touchstart", function (e) { sx = e.touches[0].clientX; }, { passive: true });
      box.addEventListener("touchend", function (e) {
        var dx = e.changedTouches[0].clientX - sx;
        if (dx > 60) { lbShow(lb.i - 1); }
        if (dx < -60) { lbShow(lb.i + 1); }
      }, { passive: true });
    }
  }

  /* ---------- FAQ Accordion ---------- */
  function renderFaq() {
    var wrap = $("#smFaq");
    if (!wrap) { return; }
    wrap.innerHTML = SM_CONFIG.faq.map(function (f, i) {
      return '<div class="sm-faq-item">' +
        '<button class="sm-faq-q" type="button" id="faqq' + i + '" aria-expanded="false" aria-controls="faqa' + i + '">' +
        "<span>" + esc(f[0]) + '</span><i aria-hidden="true">+</i></button>' +
        '<div class="sm-faq-a" id="faqa' + i + '" role="region" aria-labelledby="faqq' + i + '"><p>' + esc(f[1]) + "</p></div>" +
        "</div>";
    }).join("");
    wrap.addEventListener("click", function (e) {
      var q = e.target.closest(".sm-faq-q");
      if (!q) { return; }
      var item = q.parentNode;
      var panel = item.querySelector(".sm-faq-a");
      var open = item.classList.toggle("open");
      q.setAttribute("aria-expanded", open ? "true" : "false");
      panel.style.maxHeight = open ? panel.scrollHeight + "px" : "0px";
    });
  }

  /* ---------- Navigation Logic & Mobile Menu ---------- */
  function initNav() {
    var nav = $("#smNav"), burger = $("#smBurger"), menu = $("#smMobile"), close = $("#smClose");
    var onScroll = function () {
      if (nav) { nav.classList.toggle("is-stuck", window.scrollY > 10); }
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();

    function openMenu(state) {
      if (!menu) { return; }
      menu.classList.toggle("open", state);
      document.body.classList.toggle("sm-lock", state);
      if (burger) { burger.setAttribute("aria-expanded", state ? "true" : "false"); }
      if (state && close) { close.focus(); }
    }
    if (burger) { burger.addEventListener("click", function () { openMenu(true); }); }
    if (close) { close.addEventListener("click", function () { openMenu(false); }); }
    if (menu) {
      menu.addEventListener("click", function (e) {
        if (e.target.closest("a")) { openMenu(false); }
      });
    }
    document.addEventListener("keydown", function (e) {
      if (e.key !== "Escape") { return; }
      if (lb.open) { lbClose(); return; }
      if (menu && menu.classList.contains("open")) { openMenu(false); }
    });

    /* Active Link Intersection Observer */
    var links = $$("#smMenu a");
    var sections = links.map(function (a) { return document.querySelector(a.getAttribute("href")); });
    if ("IntersectionObserver" in window) {
      var io = new IntersectionObserver(function (entries) {
        entries.forEach(function (en) {
          if (!en.isIntersecting) { return; }
          links.forEach(function (a, i) { a.classList.toggle("active", sections[i] === en.target); });
        });
      }, { rootMargin: "-45% 0px -50% 0px" });
      sections.forEach(function (s) { if (s) { io.observe(s); } });
    }
  }

  /* ---------- Form Handling ---------- */
  function initForms() {
    var solar = $("#smSolarForm");
    if (solar) {
      solar.addEventListener("submit", function (e) {
        e.preventDefault();
        var d = new FormData(solar);
        var msg = "Hello SM Traders, I would like to enquire about rooftop solar.\n" +
          "Monthly Bill: " + (d.get("bill") || "-") + "\n" +
          "Property: " + (d.get("property") || "-") + "\n" +
          "Roof: " + (d.get("roof") || "-") + "\n" +
          "Location: " + (d.get("location") || "-");
        window.open(waLink(msg), "_blank", "noopener");
      });
    }

    var form = $("#smForm");
    if (!form) { return; }
    form.addEventListener("submit", function (e) {
      e.preventDefault();
      var out = $("#smFormMsg");
      var ok = true;
      var name = $("#cf1"), phone = $("#cf2");
      [name, phone].forEach(function (el) {
        var valid = el.value.trim().length > 1;
        if (el === phone) { valid = el.value.replace(/[^0-9]/g, "").length >= 8; }
        el.parentNode.classList.toggle("err", !valid);
        el.setAttribute("aria-invalid", valid ? "false" : "true");
        if (!valid) { ok = false; }
      });
      if (!ok) {
        if (out) { out.textContent = "Please enter your name and a valid phone number."; }
        return;
      }
      var d = new FormData(form);
      var msg = "Hello SM Traders, I would like to enquire.\n" +
        "Name: " + d.get("name") + "\n" +
        "Phone: " + d.get("phone") + "\n" +
        "Service: " + (d.get("service") || "-") + "\n" +
        "Location: " + (d.get("location") || "-") + "\n" +
        "Message: " + (d.get("message") || "-");
      if (out) { out.textContent = "Opening WhatsApp with your enquiry..."; }
      window.open(waLink(msg), "_blank", "noopener");
    });
  }

  /* ---------- Scroll Reveal Observer ---------- */
  function initReveal() {
    var els = $$(".reveal");
    if (!("IntersectionObserver" in window)) {
      els.forEach(function (el) { el.classList.add("in"); });
      return;
    }
    var io = new IntersectionObserver(function (entries) {
      entries.forEach(function (en) {
        if (en.isIntersecting) { en.target.classList.add("in"); io.unobserve(en.target); }
      });
    }, { rootMargin: "0px 0px -8% 0px", threshold: 0.08 });
    els.forEach(function (el) { io.observe(el); });
  }

  function boot() {
    try {
      applyConfig();
      renderOwners();
      renderProducts();
      renderProjects();
      initFilters();
      initLightbox();
      renderFaq();
      initNav();
      initForms();
      initReveal();
    } catch (err) {
      if (window.console && console.warn) { console.warn("SM Traders init:", err); }
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", boot);
  } else {
    boot();
  }
})();
//
